<?php
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
$testName = 'luna_issue_test_' . bin2hex(random_bytes(6));
$server = new PDO('mysql:host=127.0.0.1;port=3306;charset=utf8mb4', 'root', '', [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$server->exec("CREATE DATABASE `$testName`");
putenv('BARANGAY_DB_NAME='.$testName);
function issue_check(bool $ok, string $message): void { if (!$ok) throw new RuntimeException($message); echo "PASS: $message\n"; }
function issue_reject(callable $call, string $message): void { $rejected=false; try { $call(); } catch (InvalidArgumentException $e) { $rejected=true; } issue_check($rejected,$message); }
try {
  $server->exec("USE `$testName`");
  $schema=file_get_contents(__DIR__.'/../database/schema.sql');
  $schema=preg_replace('/CREATE DATABASE IF NOT EXISTS barangay_luna_system.*?;/s','',$schema);
  $server->exec(str_replace('USE barangay_luna_system;','',$schema));
  require_once __DIR__.'/../includes/staff-functions.php';
  require_once __DIR__.'/../includes/admin-functions.php';
  $db=barangay_db();
  $insertUser=$db->prepare("INSERT INTO users (user_code,role,full_name,username,password_hash,status) VALUES (?,?,'Test Account',?,'not-a-login-password','Active')");
  $insertUser->execute(['TEST-STAFF','staff','test-staff']); $staffId=(int)$db->lastInsertId();
  $insertUser->execute(['TEST-RES','resident','test-res']); $residentId=(int)$db->lastInsertId();
  $accountCount = (int) $db->query('SELECT COUNT(*) FROM users')->fetchColumn();
  barangay_issuance_schema(); barangay_ensure_document_fee_schema(); barangay_ensure_document_request_detail_columns();
  issue_check(barangay_issuance_payment_input(['payment_mode'=>'paid'],0)===null,'Free documents require no payment');
  issue_check(barangay_issuance_payment_input(['payment_mode'=>'unpaid'],50)===null,'Unpaid documents can be prepared');
  issue_reject(fn()=>barangay_issuance_payment_input(['payment_mode'=>'paid','amount_paid'=>'49'],50),'Underpayment rejected');
  issue_reject(fn()=>barangay_issuance_payment_input(['payment_mode'=>'paid','amount_paid'=>'51'],50),'Altered amount above the Admin fee rejected');
  issue_check(barangay_issuance_payment_input(['payment_mode'=>'paid','amount_paid'=>'150.75'],150.75)['amount']===150.75,'Exact Admin fee with centavos accepted');
  $insertDoc=$db->prepare("INSERT INTO issued_documents (document_number,resident_user_id,resident_name,document_type,fee_amount,issuance_status,request_code,applicant_details) VALUES (?,?,?,'Barangay Certification',?,'Ready for Pickup',?,?)");
  $insertDoc->execute(['TEST-WALKIN',null,'Walk-in Applicant',50,null,json_encode(['address'=>'Test address','mobile'=>''])]); $walkinId=(int)$db->lastInsertId();
  issue_check((int)$db->query("SELECT COUNT(*) FROM issued_documents WHERE issuance_status = 'Released'")->fetchColumn() === 0, 'Preparing a document does not add to released records or counts');
  $beforeRelease = staff_load_dashboard_data(['id'=>$staffId,'role'=>'staff']);
  issue_check(count($beforeRelease['issuedDocuments']) === 0 && count($beforeRelease['preparedDocuments']) === 1 && (int)$beforeRelease['staffStats']['issued_today'] === 0 && (int)$beforeRelease['serviceReports']['issued_today'] === 0 && count($beforeRelease['serviceSummary']) === 0, 'Dashboard and reports exclude prepared documents and retain resume access');
  $beforeTrend = admin_monthly_activity_trends(6);
  issue_check(array_sum($beforeTrend['series']['documents']['values']) === 0, 'Analytics excludes prepared documents');
  issue_reject(fn()=>barangay_issuance_release($walkinId,$staffId),'Unpaid walk-in cannot be released');
  issue_check($db->query('SELECT COUNT(*) FROM document_payments')->fetchColumn()==0,'Failed release rolls back payment entries');
  issue_reject(fn()=>barangay_issuance_release($walkinId,$staffId,['payment_mode'=>'paid','amount_paid'=>'50','handed_over'=>'1']),'Handover alone cannot record payment or release an unpaid document');
  issue_check($db->query('SELECT issuance_status FROM issued_documents WHERE id='.$walkinId)->fetchColumn()==='Ready for Pickup','Missing payment confirmation keeps the document ready for pickup');
  $unconfirmedPayment=barangay_find_document_payment(null,'TEST-WALKIN');
  issue_check(($unconfirmedPayment['status'] ?? '')!=='Paid','Missing confirmation does not mark payment as paid');
  issue_check(barangay_issuance_release($walkinId,$staffId,['payment_mode'=>'paid','payment_received_confirmed'=>'1','amount_paid'=>'50','receipt_number'=>'TEST-RECEIPT']),'Payment and walk-in release saved together');
  issue_check((int)$db->query("SELECT COUNT(*) FROM issued_documents WHERE issuance_status = 'Released' AND released_at IS NOT NULL AND DATE(issued_at) = CURDATE()")->fetchColumn() === 1, 'Confirm Release adds the issued record with the actual release date');
  $afterRelease = staff_load_dashboard_data(['id'=>$staffId,'role'=>'staff']);
  issue_check(count($afterRelease['issuedDocuments']) === 1 && count($afterRelease['preparedDocuments']) === 0 && (int)$afterRelease['staffStats']['issued_today'] === 1 && (int)$afterRelease['serviceReports']['issued_today'] === 1, 'Confirm Release updates dashboard, reports and prepared queue together');
  $afterTrend = admin_monthly_activity_trends(6);
  issue_check((int)$afterTrend['series']['documents']['values'][date('Y-m')] === 1 && admin_count('issued_documents', "issuance_status = 'Released'") === 1, 'Analytics counts unregistered walk-in release in its release month');
  $payment=barangay_find_document_payment(null,'TEST-WALKIN');
  issue_check($payment['status']==='Paid' && (float)$payment['amount_paid']===50.0 && $payment['receipt_number']==='TEST-RECEIPT','Ledger records amount, receipt and staff');
  issue_check(!barangay_issuance_release($walkinId,$staffId),'Repeated release does not duplicate payments');
  issue_check((int)$db->query('SELECT COUNT(*) FROM users')->fetchColumn()===$accountCount,'Unregistered walk-in does not create an account');
  $insertDoc->execute(['TEST-FREE',null,'Free Applicant',0,null,'{}']); $freeId=(int)$db->lastInsertId();
  issue_check(barangay_issuance_release($freeId,$staffId),'Free walk-in can be released');
  issue_check($db->query('SELECT COUNT(*) FROM document_payments')->fetchColumn()==1,'Free issuance adds no payment entry');
  $req=$db->prepare("INSERT INTO document_requests (request_code,resident_user_id,resident_name,document_type,fee_amount,status) VALUES ('TEST-REQUEST',?,'Online Applicant','Barangay Certification',25,'Ready for Pickup')"); $req->execute([$residentId]);
  $insertDoc->execute(['TEST-ONLINE',$residentId,'Online Applicant',25,'TEST-REQUEST','{}']); $onlineId=(int)$db->lastInsertId();
  issue_reject(fn()=>barangay_issuance_release($onlineId,$staffId,['payment_mode'=>'paid','amount_paid'=>'10']),'Online release rejects incomplete payment');
  issue_check($db->query("SELECT status FROM document_requests WHERE request_code='TEST-REQUEST'")->fetchColumn()==='Ready for Pickup','Rejected release leaves request ready');
  issue_check(barangay_issuance_release($onlineId,$staffId,['payment_mode'=>'paid','payment_received_confirmed'=>'1','amount_paid'=>'25']),'Online request releases after payment');
  issue_check($db->query("SELECT status FROM document_requests WHERE request_code='TEST-REQUEST'")->fetchColumn()==='Released','Online request and issued document statuses stay synchronized');
  $finalTrend = admin_monthly_activity_trends(6);
  issue_check((int)$finalTrend['series']['documents']['values'][date('Y-m')] === 3 && admin_count('issued_documents', "issuance_status = 'Released'") === 3, 'Analytics includes paid, free and online releases once each');
  $defaults=sms_automatic_defaults();
  issue_check(isset($defaults['received'],$defaults['rejected'],$defaults['ready'],$defaults['released']),'Automatic SMS supports all document events');
  $db->exec("INSERT INTO system_settings (setting_key,setting_value) VALUES ('sms_enabled','0') ON DUPLICATE KEY UPDATE setting_value='0'");
  barangay_safe_request_sms('received','TEST-REQUEST',$staffId);
  issue_check($db->query('SELECT COUNT(*) FROM sms_logs')->fetchColumn()==0,'Disabled SMS does not send and does not undo documents');
  issue_reject(fn()=>barangay_remove_prepared_document($walkinId),'Released documents cannot be removed');
  $insertDoc->execute(['TEST-REMOVE',null,'Remove Applicant',10,null,'{}']); $removeId=(int)$db->lastInsertId();
  $pendingId=barangay_ensure_released_document_payment(['document_number'=>'TEST-REMOVE','resident_name'=>'Remove Applicant','document_type'=>'Barangay Certification','amount_due'=>10]);
  issue_check(barangay_remove_prepared_document($removeId),'Prepared entry can be removed');
  issue_check(!barangay_remove_prepared_document($removeId),'Repeated removal is safe');
  issue_check(barangay_find_document_payment(null,'TEST-REMOVE')['status']==='Voided','Unpaid removed preparation is excluded from collections');
  issue_reject(fn()=>barangay_issuance_release($removeId,$staffId),'Removed document cannot be released');
  $insertDoc->execute(['TEST-REMOVE-PAID',null,'Paid Remove Applicant',10,null,'{}']); $paidRemoveId=(int)$db->lastInsertId();
  $paidId=barangay_ensure_released_document_payment(['document_number'=>'TEST-REMOVE-PAID','resident_name'=>'Paid Remove Applicant','document_type'=>'Barangay Certification','amount_due'=>10]);
  issue_reject(fn()=>barangay_record_walk_in_payment($paidId,9,'','Test',$staffId),'Ledger rejects amount below Admin fee');
  issue_reject(fn()=>barangay_record_walk_in_payment($paidId,11,'','Test',$staffId),'Ledger rejects amount above Admin fee');
  issue_check(barangay_find_document_payment(null,'TEST-REMOVE-PAID')['status']==='Pending','Altered amounts leave payment unpaid');
  barangay_record_walk_in_payment($paidId,10,'TEST-KEEP','Test',$staffId);
  barangay_remove_prepared_document($paidRemoveId);
  issue_check(barangay_find_document_payment(null,'TEST-REMOVE-PAID')['status']==='Paid','Collected payment stays intact after removal');
  $db->prepare("INSERT INTO document_requests (request_code,resident_user_id,resident_name,document_type,fee_amount,status) VALUES ('TEST-REPREPARE',?,'Online Applicant','Barangay Certification',0,'Ready for Pickup')")->execute([$residentId]);
  $insertDoc->execute(['TEST-REMOVE-ONLINE',$residentId,'Online Applicant',0,'TEST-REPREPARE','{}']); $onlineRemoveId=(int)$db->lastInsertId();
  $onlinePending=barangay_ensure_released_document_payment(['request_code'=>'TEST-REPREPARE','document_number'=>'TEST-REMOVE-ONLINE','resident_name'=>'Online Applicant','document_type'=>'Barangay Certification','amount_due'=>10]);
  barangay_remove_prepared_document($onlineRemoveId);
  $onlineReplacement=barangay_ensure_released_document_payment(['request_code'=>'TEST-REPREPARE','document_number'=>'TEST-NEW-ONLINE','resident_name'=>'Online Applicant','document_type'=>'Barangay Certification','amount_due'=>10]);
  issue_check($onlineReplacement!==$onlinePending && barangay_find_document_payment('TEST-REPREPARE','TEST-NEW-ONLINE')['status']==='Pending','Preparing again uses a new payable entry instead of a voided payment');
  issue_check($db->query("SELECT status FROM document_requests WHERE request_code='TEST-REPREPARE'")->fetchColumn()==='Approved','Removed online preparation can be prepared again');
} finally { $server->exec("DROP DATABASE `$testName`"); }
echo "Isolated database removed. No SMS sent.\n";
